/// <summary>
/// Common Logic block for blocks in the Mobile WMS model, mainly handles naming
/// </summary>
class MwmsLogicBlock extends TFMLogicBlock
{

}

Method.Source:
/// <summary>
/// Name of the block Type. Override this method if you want to give the block a translated label, instead of the generated for the Class name.
/// </summary>
/// <returns>Name of the block</returns>
public Name blockName()
{
    return TFMHelper::convertCamelCaseToNiceText(subStr(classId2Name(classIdGet(this)),strLen(classStr(MwmsLogicBlock))+1,100));
}
